//! Auto-generated Python code generation for Polyglot Lab.

use anyhow::Result;
use lab_node_sdk::GraphSpec;
use std::collections::{HashMap, HashSet};

/// Generates `requirements.txt` content.
pub fn generate_requirements_txt(has_network: bool) -> String {
    let mut reqs = String::from("# Requirements generated by Polyglot Lab\n");
    if has_network {
        reqs.push_str("requests>=2.31.0\n");
    }
    reqs
}

/// Generates `nodes.py` with self-contained implementations of the required atomic nodes.
pub fn generate_nodes_py(used_kinds: &HashSet<&str>) -> String {
    let mut code = String::from(
        r#"# Code generated by Polyglot Lab. DO NOT EDIT.
from __future__ import annotations
import asyncio
import json
import os
import re
import time
from typing import Any, Optional

"#,
    );

    if used_kinds.contains("http_get") {
        code.push_str(
            r#"async def http_get(url: str) -> str:
    import urllib.request
    print(f"   Fetching: {url}")
    req = urllib.request.Request(url, headers={"User-Agent": "PolyglotLab-Export/0.4.0"})
    loop = asyncio.get_event_loop()
    def _fetch():
        with urllib.request.urlopen(req, timeout=30) as resp:
            return resp.read().decode("utf-8")
    return await loop.run_in_executor(None, _fetch)

"#,
        );
    }

    if used_kinds.contains("fs_read") {
        code.push_str(
            r#"def fs_read(path: str) -> str:
    print(f"   Reading file: {path}")
    with open(path, "r", encoding="utf-8") as f:
        return f.read()

"#,
        );
    }

    if used_kinds.contains("fs_write") {
        code.push_str(
            r#"def fs_write(path: str, content: str) -> int:
    print(f"   Writing to file: {path}")
    parent = os.path.dirname(path)
    if parent:
        os.makedirs(parent, exist_ok=True)
    with open(path, "w", encoding="utf-8") as f:
        f.write(content)
    return len(content.encode("utf-8"))

"#,
        );
    }

    if used_kinds.contains("log_output") {
        code.push_str(
            r#"def log_output(text: Any) -> None:
    print(f"   Log Output: {text}")

"#,
        );
    }

    if used_kinds.contains("json_parse") {
        code.push_str(
            r#"def select_path(val: Any, path: str) -> Any:
    parts = [p for p in path.strip(".").split(".") if p]
    curr = val
    for part in parts:
        if isinstance(curr, dict):
            if part not in curr:
                raise KeyError(f"Key '{part}' not found in path '{path}'")
            curr = curr[part]
        elif isinstance(curr, list):
            idx = int(part)
            curr = curr[idx]
        else:
            raise TypeError(f"Cannot navigate through non-container value at '{part}'")
    return curr

def json_parse(raw: str, path: str = "") -> Any:
    parsed = json.loads(raw)
    if not path:
        return parsed
    return select_path(parsed, path)

"#,
        );
    }

    if used_kinds.contains("text_clean") {
        code.push_str(
            r#"def text_clean(text: str, trim: bool = True, collapse: bool = False, to_lower: bool = False, to_upper: bool = False) -> str:
    if to_lower and to_upper:
        raise ValueError("'to_lower' and 'to_upper' cannot both be true")
    res = text
    if trim:
        res = res.strip()
    if collapse:
        lead = not trim and bool(res) and res[0].isspace()
        trail = not trim and bool(res) and res[-1].isspace()
        core = " ".join(res.split())
        res = (" " if lead else "") + core + (" " if trail and core else "")
    if to_lower:
        res = res.lower()
    if to_upper:
        res = res.upper()
    return res

"#,
        );
    }

    if used_kinds.contains("delay") {
        code.push_str(
            r#"async def delay(duration_str: str) -> None:
    text = duration_str.strip()
    match = re.match(r"^(\d+)(ms|s|m)$", text)
    if not match:
        raise ValueError(f"Invalid duration format: '{text}'")
    val, unit = int(match.group(1)), match.group(2)
    secs = val / 1000.0 if unit == "ms" else (val * 60.0 if unit == "m" else float(val))
    print(f"   Sleeping for {secs}s")
    await asyncio.sleep(secs)

"#,
        );
    }

    if used_kinds.contains("string_to_path") {
        code.push_str(
            r#"def string_to_path(raw: str) -> str:
    trimmed = raw.strip()
    if not trimmed:
        raise ValueError("Path cannot be empty")
    return trimmed

"#,
        );
    }

    if used_kinds.contains("json_to_string") {
        code.push_str(
            r#"def json_to_string(val: Any) -> str:
    if isinstance(val, str):
        return val
    return json.dumps(val)

"#,
        );
    }

    if used_kinds.contains("json_to_bool") {
        code.push_str(
            r#"def json_to_bool(val: Any) -> bool:
    if isinstance(val, bool):
        return val
    if isinstance(val, str):
        return val.lower() in ("true", "1", "yes")
    return bool(val)

"#,
        );
    }

    code
}

fn python_string_literal(value: &str) -> String {
    format!("{value:?}")
}

/// Generates Python code statement for a single node.
pub fn generate_python_node_call(
    node: &lab_node_sdk::NodeInstance,
    graph: &GraphSpec,
    indent: &str,
) -> String {
    let mut out = format!("{indent}# 🚀 Node: '{}' ({})\n", node.id, node.kind);
    let id_ident = crate::codegen::sanitize_ident(&node.id);

    let mut in_edges: HashMap<&str, (&str, &str)> = HashMap::new();
    for edge in &graph.edges {
        if edge.to.node == node.id {
            in_edges.insert(&edge.to.port, (&edge.from.node, &edge.from.port));
        }
    }

    match node.kind.as_str() {
        "http_get" => {
            let url_expr = if let Some(&(src, sport)) = in_edges.get("url") {
                format!(
                    "{}_{}",
                    crate::codegen::sanitize_ident(src),
                    crate::codegen::sanitize_ident(sport)
                )
            } else {
                let u = node
                    .config
                    .get("url")
                    .and_then(|v| v.as_str())
                    .unwrap_or("");
                python_string_literal(u)
            };
            out.push_str(&format!(
                "{indent}{id_ident}_body = await nodes.http_get({url_expr})\n"
            ));
        }
        "fs_read" => {
            let path_expr = if let Some(&(src, sport)) = in_edges.get("path") {
                format!(
                    "{}_{}",
                    crate::codegen::sanitize_ident(src),
                    crate::codegen::sanitize_ident(sport)
                )
            } else {
                let p = node
                    .config
                    .get("path")
                    .and_then(|v| v.as_str())
                    .unwrap_or("");
                python_string_literal(p)
            };
            out.push_str(&format!(
                "{indent}{id_ident}_content = nodes.fs_read({path_expr})\n"
            ));
        }
        "fs_write" => {
            let path_expr = if let Some(&(src, sport)) = in_edges.get("path") {
                format!(
                    "{}_{}",
                    crate::codegen::sanitize_ident(src),
                    crate::codegen::sanitize_ident(sport)
                )
            } else {
                let p = node
                    .config
                    .get("path")
                    .and_then(|v| v.as_str())
                    .unwrap_or("");
                python_string_literal(p)
            };
            let content_expr = if let Some(&(src, sport)) = in_edges.get("content") {
                format!(
                    "{}_{}",
                    crate::codegen::sanitize_ident(src),
                    crate::codegen::sanitize_ident(sport)
                )
            } else {
                let c = node
                    .config
                    .get("content")
                    .and_then(|v| v.as_str())
                    .unwrap_or("");
                python_string_literal(c)
            };
            out.push_str(&format!(
                "{indent}{id_ident}_bytes_written = nodes.fs_write({path_expr}, {content_expr})\n"
            ));
        }
        "log_output" => {
            let text_expr = if let Some(&(src, sport)) = in_edges.get("text") {
                format!(
                    "{}_{}",
                    crate::codegen::sanitize_ident(src),
                    crate::codegen::sanitize_ident(sport)
                )
            } else {
                let t = node
                    .config
                    .get("text")
                    .and_then(|v| v.as_str())
                    .unwrap_or("");
                python_string_literal(t)
            };
            out.push_str(&format!("{indent}nodes.log_output({text_expr})\n"));
        }
        "json_parse" => {
            let json_expr = if let Some(&(src, sport)) = in_edges.get("json_str") {
                format!(
                    "{}_{}",
                    crate::codegen::sanitize_ident(src),
                    crate::codegen::sanitize_ident(sport)
                )
            } else {
                let j = node
                    .config
                    .get("json_str")
                    .and_then(|v| v.as_str())
                    .unwrap_or("{}");
                python_string_literal(j)
            };
            let path_expr = if let Some(&(src, sport)) = in_edges.get("path") {
                format!(
                    "{}_{}",
                    crate::codegen::sanitize_ident(src),
                    crate::codegen::sanitize_ident(sport)
                )
            } else {
                let p = node
                    .config
                    .get("path")
                    .and_then(|v| v.as_str())
                    .unwrap_or("");
                python_string_literal(p)
            };
            out.push_str(&format!(
                "{indent}{id_ident}_value = nodes.json_parse({json_expr}, {path_expr})\n"
            ));
        }
        "text_clean" => {
            let text_expr = if let Some(&(src, sport)) = in_edges.get("text") {
                format!(
                    "{}_{}",
                    crate::codegen::sanitize_ident(src),
                    crate::codegen::sanitize_ident(sport)
                )
            } else {
                let t = node
                    .config
                    .get("text")
                    .and_then(|v| v.as_str())
                    .unwrap_or("");
                python_string_literal(t)
            };
            let trim = if node
                .config
                .get("trim")
                .and_then(|v| v.as_bool())
                .unwrap_or(true)
            {
                "True"
            } else {
                "False"
            };
            let collapse = if node
                .config
                .get("collapse")
                .and_then(|v| v.as_bool())
                .unwrap_or(false)
            {
                "True"
            } else {
                "False"
            };
            let to_lower = if node
                .config
                .get("to_lower")
                .and_then(|v| v.as_bool())
                .unwrap_or(false)
            {
                "True"
            } else {
                "False"
            };
            let to_upper = if node
                .config
                .get("to_upper")
                .and_then(|v| v.as_bool())
                .unwrap_or(false)
            {
                "True"
            } else {
                "False"
            };
            out.push_str(&format!("{indent}{id_ident}_cleaned = nodes.text_clean({text_expr}, trim={trim}, collapse={collapse}, to_lower={to_lower}, to_upper={to_upper})\n"));
        }
        "delay" => {
            let dur_expr = if let Some(&(src, sport)) = in_edges.get("duration") {
                format!(
                    "{}_{}",
                    crate::codegen::sanitize_ident(src),
                    crate::codegen::sanitize_ident(sport)
                )
            } else {
                let d = node
                    .config
                    .get("duration")
                    .and_then(|v| v.as_str())
                    .unwrap_or("0ms");
                python_string_literal(d)
            };
            out.push_str(&format!("{indent}await nodes.delay({dur_expr})\n"));
        }
        "string_to_path" => {
            let path_expr = if let Some(&(src, sport)) = in_edges.get("path") {
                format!(
                    "{}_{}",
                    crate::codegen::sanitize_ident(src),
                    crate::codegen::sanitize_ident(sport)
                )
            } else {
                let p = node
                    .config
                    .get("path")
                    .and_then(|v| v.as_str())
                    .unwrap_or("");
                python_string_literal(p)
            };
            out.push_str(&format!(
                "{indent}{id_ident}_path = nodes.string_to_path({path_expr})\n"
            ));
        }
        "json_to_string" => {
            let val_expr = if let Some(&(src, sport)) = in_edges.get("value") {
                format!(
                    "{}_{}",
                    crate::codegen::sanitize_ident(src),
                    crate::codegen::sanitize_ident(sport)
                )
            } else {
                "\"\"".to_string()
            };
            out.push_str(&format!(
                "{indent}{id_ident}_text = nodes.json_to_string({val_expr})\n"
            ));
        }
        "json_to_bool" => {
            let val_expr = if let Some(&(src, sport)) = in_edges.get("value") {
                format!(
                    "{}_{}",
                    crate::codegen::sanitize_ident(src),
                    crate::codegen::sanitize_ident(sport)
                )
            } else {
                "False".to_string()
            };
            out.push_str(&format!(
                "{indent}{id_ident}_value = nodes.json_to_bool({val_expr})\n"
            ));
        }
        _ => {}
    }

    out
}

/// Generates `main.py` with async/await topological execution and branching if/else.
pub fn generate_main_py(graph: &GraphSpec, topo_order: &[String]) -> Result<String> {
    let node_map: HashMap<&str, &lab_node_sdk::NodeInstance> =
        graph.nodes.iter().map(|n| (n.id.as_str(), n)).collect();

    let conditions: Vec<&lab_node_sdk::NodeInstance> = graph
        .nodes
        .iter()
        .filter(|n| n.kind == "condition")
        .collect();

    let mut body = String::new();

    if conditions.is_empty() {
        for id in topo_order {
            if let Some(node) = node_map.get(id.as_str()) {
                body.push_str(&generate_python_node_call(node, graph, "    "));
            }
        }
    } else {
        let cond = conditions[0];
        let true_target = cond
            .config
            .get("true_branch")
            .and_then(|v| v.as_str())
            .unwrap_or("");
        let false_target = cond
            .config
            .get("false_branch")
            .and_then(|v| v.as_str())
            .unwrap_or("");

        let reach_true = crate::codegen::reachable_from(true_target, graph);
        let reach_false = crate::codegen::reachable_from(false_target, graph);

        let true_exclusive: HashSet<_> = reach_true.difference(&reach_false).cloned().collect();
        let false_exclusive: HashSet<_> = reach_false.difference(&reach_true).cloned().collect();

        // 1. Nodes before condition
        let cond_idx = topo_order.iter().position(|id| id == &cond.id).unwrap_or(0);
        for id in &topo_order[..cond_idx] {
            if let Some(node) = node_map.get(id.as_str()) {
                body.push_str(&generate_python_node_call(node, graph, "    "));
            }
        }

        // 2. Condition evaluation
        let cond_val_expr = if let Some(edge) = graph
            .edges
            .iter()
            .find(|e| e.to.node == cond.id && e.to.port == "value")
        {
            format!(
                "{}_{}",
                crate::codegen::sanitize_ident(&edge.from.node),
                crate::codegen::sanitize_ident(&edge.from.port)
            )
        } else {
            let b = cond
                .config
                .get("value")
                .and_then(|v| v.as_bool())
                .unwrap_or(false);
            if b {
                "True".to_string()
            } else {
                "False".to_string()
            }
        };

        body.push_str(&format!(
            "    # 🌿 Branching Condition: '{}'\n    if {cond_val_expr}:\n",
            cond.id
        ));

        // True branch nodes in topological order
        let mut true_count = 0;
        for id in topo_order {
            if true_exclusive.contains(id) {
                if let Some(node) = node_map.get(id.as_str()) {
                    body.push_str(&generate_python_node_call(node, graph, "        "));
                    true_count += 1;
                }
            }
        }
        if true_count == 0 {
            body.push_str("        pass\n");
        }

        body.push_str("    else:\n");

        // False branch nodes in topological order
        let mut false_count = 0;
        for id in topo_order {
            if false_exclusive.contains(id) {
                if let Some(node) = node_map.get(id.as_str()) {
                    body.push_str(&generate_python_node_call(node, graph, "        "));
                    false_count += 1;
                }
            }
        }
        if false_count == 0 {
            body.push_str("        pass\n");
        }

        body.push('\n');
    }

    let code = format!(
        r#"# Code generated by Polyglot Lab. DO NOT EDIT.
import asyncio
import nodes

async def main() -> None:
    print("🚀 Starting exported Python application...")

{body}
    print("✅ Application finished successfully!")

if __name__ == "__main__":
    asyncio.run(main())
"#
    );

    Ok(code)
}
